import{_ as t,o as a,c as s,a4 as n}from"./chunks/framework.BWWfBZka.js";const u=JSON.parse('{"title":"52-Week Learning Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"en/03_Roadmap.md","filePath":"en/03_Roadmap.md","lastUpdated":1788996924000}'),o={name:"en/03_Roadmap.md"};function i(r,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_52-week-learning-roadmap" tabindex="-1">52-Week Learning Roadmap <a class="header-anchor" href="#_52-week-learning-roadmap" aria-label="Permalink to &quot;52-Week Learning Roadmap&quot;">​</a></h1><blockquote><p><em>52-week plan from prerequisites through to company-specific preparation.</em></p></blockquote><hr><p><strong>Curriculum Phases</strong>: 14 stages spanning 52 weeks</p><h2 id="📅-overview-timeline" tabindex="-1">📅 Overview Timeline <a class="header-anchor" href="#📅-overview-timeline" aria-label="Permalink to &quot;📅 Overview Timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Phase</th><th style="text-align:left;">Timeline</th><th style="text-align:left;">Theme</th><th style="text-align:left;">Milestone / Proof</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Phase 0</strong></td><td style="text-align:left;"><code>Weeks 1-3</code></td><td style="text-align:left;"><strong>Prerequisites and vocabulary</strong></td><td style="text-align:left;">You can explain what happens when you type a URL, in detail.</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Phase 0</strong></td><td style="text-align:left;"><code>Weeks 3-6</code></td><td style="text-align:left;"><strong>Estimation and requirements</strong></td><td style="text-align:left;">You can size a system in five minutes with defensible numbers.</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Phase 1</strong></td><td style="text-align:left;"><code>Weeks 6-10</code></td><td style="text-align:left;"><strong>The building blocks</strong></td><td style="text-align:left;">You can name the right component for a requirement without hesitating.</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Phase 1</strong></td><td style="text-align:left;"><code>Weeks 10-14</code></td><td style="text-align:left;"><strong>Databases in depth</strong></td><td style="text-align:left;">You can defend a database choice against a challenging follow-up.</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Phase 2</strong></td><td style="text-align:left;"><code>Weeks 14-18</code></td><td style="text-align:left;"><strong>Distributed systems theory</strong></td><td style="text-align:left;">You understand why distributed systems are hard, not just that they are.</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Phase 2</strong></td><td style="text-align:left;"><code>Weeks 18-22</code></td><td style="text-align:left;"><strong>Caching and messaging</strong></td><td style="text-align:left;">You can explain cache invalidation and exactly-once honestly, including the caveats.</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Phase 3</strong></td><td style="text-align:left;"><code>Weeks 22-28</code></td><td style="text-align:left;"><strong>Core case studies</strong></td><td style="text-align:left;">You can design any of the classic eight from a blank page in 45 minutes.</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Phase 3</strong></td><td style="text-align:left;"><code>Weeks 28-32</code></td><td style="text-align:left;"><strong>Harder case studies</strong></td><td style="text-align:left;">You can go three follow-up questions deep on any component you drew.</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Phase 4</strong></td><td style="text-align:left;"><code>Weeks 32-35</code></td><td style="text-align:left;"><strong>Reliability and operations</strong></td><td style="text-align:left;">Every design you produce now includes a failure discussion unprompted.</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Phase 4</strong></td><td style="text-align:left;"><code>Weeks 35-38</code></td><td style="text-align:left;"><strong>Observability and security</strong></td><td style="text-align:left;">You can answer &#39;how would you know it broke&#39; for any system you design.</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Phase 5</strong></td><td style="text-align:left;"><code>Weeks 38-42</code></td><td style="text-align:left;"><strong>Low level design</strong></td><td style="text-align:left;">You can produce a clean class design and defend each abstraction.</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Phase 5</strong></td><td style="text-align:left;"><code>Weeks 42-45</code></td><td style="text-align:left;"><strong>Real architectures</strong></td><td style="text-align:left;">You can cite how a real company solved a problem you are designing.</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Phase 6</strong></td><td style="text-align:left;"><code>Weeks 45-48</code></td><td style="text-align:left;"><strong>Mock interviews</strong></td><td style="text-align:left;">You can fill 45 minutes with structure, not filler.</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Phase 6</strong></td><td style="text-align:left;"><code>Weeks 48-52</code></td><td style="text-align:left;"><strong>Company-specific preparation</strong></td><td style="text-align:left;">You can connect your design choices to that company&#39;s actual problems.</td></tr></tbody></table><hr><h2 id="📖-phase-by-phase-detailed-curriculum" tabindex="-1">📖 Phase-by-Phase Detailed Curriculum <a class="header-anchor" href="#📖-phase-by-phase-detailed-curriculum" aria-label="Permalink to &quot;📖 Phase-by-Phase Detailed Curriculum&quot;">​</a></h2><h3 id="_1-phase-0-weeks-1-3-prerequisites-and-vocabulary" tabindex="-1">1. Phase 0 (Weeks 1-3): Prerequisites and vocabulary <a class="header-anchor" href="#_1-phase-0-weeks-1-3-prerequisites-and-vocabulary" aria-label="Permalink to &quot;1. Phase 0 (Weeks 1-3): Prerequisites and vocabulary&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Client-server, DNS, HTTP, TLS, REST, databases, what a server actually is. Latency numbers every programmer should know.</li><li>🛠️ <strong>What to do</strong>: Write out the request path for a website you use, end to end, from keystroke to pixel.</li><li>🎯 <strong>Milestone / Proof</strong>: You can explain what happens when you type a URL, in detail.</li></ul><h3 id="_2-phase-0-weeks-3-6-estimation-and-requirements" tabindex="-1">2. Phase 0 (Weeks 3-6): Estimation and requirements <a class="header-anchor" href="#_2-phase-0-weeks-3-6-estimation-and-requirements" aria-label="Permalink to &quot;2. Phase 0 (Weeks 3-6): Estimation and requirements&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Back-of-the-envelope maths, QPS, storage and bandwidth estimation, functional versus non-functional requirements.</li><li>🛠️ <strong>What to do</strong>: Estimate storage, QPS and bandwidth for three products you use daily. Check your assumptions.</li><li>🎯 <strong>Milestone / Proof</strong>: You can size a system in five minutes with defensible numbers.</li></ul><h3 id="_3-phase-1-weeks-6-10-the-building-blocks" tabindex="-1">3. Phase 1 (Weeks 6-10): The building blocks <a class="header-anchor" href="#_3-phase-1-weeks-6-10-the-building-blocks" aria-label="Permalink to &quot;3. Phase 1 (Weeks 6-10): The building blocks&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Load balancers, caches, CDNs, proxies, API gateways, message queues, object storage. What each does and costs.</li><li>🛠️ <strong>What to do</strong>: For each block, write when you would use it, when you would not, and what it fails at.</li><li>🎯 <strong>Milestone / Proof</strong>: You can name the right component for a requirement without hesitating.</li></ul><h3 id="_4-phase-1-weeks-10-14-databases-in-depth" tabindex="-1">4. Phase 1 (Weeks 10-14): Databases in depth <a class="header-anchor" href="#_4-phase-1-weeks-10-14-databases-in-depth" aria-label="Permalink to &quot;4. Phase 1 (Weeks 10-14): Databases in depth&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: SQL versus NoSQL, indexing, replication, sharding, consistent hashing, transactions, isolation, hot partitions.</li><li>🛠️ <strong>What to do</strong>: Design schemas and sharding strategies for three different products. Justify each partition key.</li><li>🎯 <strong>Milestone / Proof</strong>: You can defend a database choice against a challenging follow-up.</li></ul><h3 id="_5-phase-2-weeks-14-18-distributed-systems-theory" tabindex="-1">5. Phase 2 (Weeks 14-18): Distributed systems theory <a class="header-anchor" href="#_5-phase-2-weeks-14-18-distributed-systems-theory" aria-label="Permalink to &quot;5. Phase 2 (Weeks 14-18): Distributed systems theory&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: CAP and PACELC, consistency models, consensus, leader election, quorums, replication lag, clock problems.</li><li>🛠️ <strong>What to do</strong>: Watch the Martin Kleppmann lecture series. Read the DDIA chapters on replication and consistency.</li><li>🎯 <strong>Milestone / Proof</strong>: You understand why distributed systems are hard, not just that they are.</li></ul><h3 id="_6-phase-2-weeks-18-22-caching-and-messaging" tabindex="-1">6. Phase 2 (Weeks 18-22): Caching and messaging <a class="header-anchor" href="#_6-phase-2-weeks-18-22-caching-and-messaging" aria-label="Permalink to &quot;6. Phase 2 (Weeks 18-22): Caching and messaging&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Cache strategies, invalidation, eviction, multi-level caching, Kafka, queues, delivery guarantees, idempotency.</li><li>🛠️ <strong>What to do</strong>: Design the caching layer and the event flow for a product you know well.</li><li>🎯 <strong>Milestone / Proof</strong>: You can explain cache invalidation and exactly-once honestly, including the caveats.</li></ul><h3 id="_7-phase-3-weeks-22-28-core-case-studies" tabindex="-1">7. Phase 3 (Weeks 22-28): Core case studies <a class="header-anchor" href="#_7-phase-3-weeks-22-28-core-case-studies" aria-label="Permalink to &quot;7. Phase 3 (Weeks 22-28): Core case studies&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: URL shortener, rate limiter, pastebin, key-value store, web crawler, notification system, chat, news feed.</li><li>🛠️ <strong>What to do</strong>: Work through the first 15 case studies on the Case Studies sheet. Write each one up before checking a solution.</li><li>🎯 <strong>Milestone / Proof</strong>: You can design any of the classic eight from a blank page in 45 minutes.</li></ul><h3 id="_8-phase-3-weeks-28-32-harder-case-studies" tabindex="-1">8. Phase 3 (Weeks 28-32): Harder case studies <a class="header-anchor" href="#_8-phase-3-weeks-28-32-harder-case-studies" aria-label="Permalink to &quot;8. Phase 3 (Weeks 28-32): Harder case studies&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Uber, Netflix, WhatsApp, Google Docs, search, payments, ticket booking, distributed scheduler.</li><li>🛠️ <strong>What to do</strong>: Work through the remaining case studies. Focus on the deep dive rather than the boxes.</li><li>🎯 <strong>Milestone / Proof</strong>: You can go three follow-up questions deep on any component you drew.</li></ul><h3 id="_9-phase-4-weeks-32-35-reliability-and-operations" tabindex="-1">9. Phase 4 (Weeks 32-35): Reliability and operations <a class="header-anchor" href="#_9-phase-4-weeks-32-35-reliability-and-operations" aria-label="Permalink to &quot;9. Phase 4 (Weeks 32-35): Reliability and operations&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Redundancy, circuit breakers, rate limiting, graceful degradation, backpressure, disaster recovery, chaos.</li><li>🛠️ <strong>What to do</strong>: Take three of your designs and add the failure story: what breaks, what the user sees, how it recovers.</li><li>🎯 <strong>Milestone / Proof</strong>: Every design you produce now includes a failure discussion unprompted.</li></ul><h3 id="_10-phase-4-weeks-35-38-observability-and-security" tabindex="-1">10. Phase 4 (Weeks 35-38): Observability and security <a class="header-anchor" href="#_10-phase-4-weeks-35-38-observability-and-security" aria-label="Permalink to &quot;10. Phase 4 (Weeks 35-38): Observability and security&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Logging, metrics, tracing, SLOs, alerting, auth at scale, encryption, secrets, DDoS, data privacy.</li><li>🛠️ <strong>What to do</strong>: Add the observability and security layer to your existing designs. Define an SLO for each.</li><li>🎯 <strong>Milestone / Proof</strong>: You can answer &#39;how would you know it broke&#39; for any system you design.</li></ul><h3 id="_11-phase-5-weeks-38-42-low-level-design" tabindex="-1">11. Phase 5 (Weeks 38-42): Low level design <a class="header-anchor" href="#_11-phase-5-weeks-38-42-low-level-design" aria-label="Permalink to &quot;11. Phase 5 (Weeks 38-42): Low level design&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: SOLID, design patterns, class diagrams, concurrency in objects, parking lot, elevator, BookMyShow, Splitwise.</li><li>🛠️ <strong>What to do</strong>: Solve 10 LLD problems with full class diagrams and working code. Amazon and Indian companies ask these directly.</li><li>🎯 <strong>Milestone / Proof</strong>: You can produce a clean class design and defend each abstraction.</li></ul><h3 id="_12-phase-5-weeks-42-45-real-architectures" tabindex="-1">12. Phase 5 (Weeks 42-45): Real architectures <a class="header-anchor" href="#_12-phase-5-weeks-42-45-real-architectures" aria-label="Permalink to &quot;12. Phase 5 (Weeks 42-45): Real architectures&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Engineering blogs from Netflix, Uber, Airbnb, Discord, Slack, Meta. How production actually differs from textbooks.</li><li>🛠️ <strong>What to do</strong>: Read two engineering blog posts a week. Write a paragraph on what surprised you in each.</li><li>🎯 <strong>Milestone / Proof</strong>: You can cite how a real company solved a problem you are designing.</li></ul><h3 id="_13-phase-6-weeks-45-48-mock-interviews" tabindex="-1">13. Phase 6 (Weeks 45-48): Mock interviews <a class="header-anchor" href="#_13-phase-6-weeks-45-48-mock-interviews" aria-label="Permalink to &quot;13. Phase 6 (Weeks 45-48): Mock interviews&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Timed 45-minute designs, thinking out loud, diagramming under pressure, handling challenging follow-ups.</li><li>🛠️ <strong>What to do</strong>: Two mock interviews weekly. Record yourself. Watch it back; it is uncomfortable and effective.</li><li>🎯 <strong>Milestone / Proof</strong>: You can fill 45 minutes with structure, not filler.</li></ul><h3 id="_14-phase-6-weeks-48-52-company-specific-preparation" tabindex="-1">14. Phase 6 (Weeks 48-52): Company-specific preparation <a class="header-anchor" href="#_14-phase-6-weeks-48-52-company-specific-preparation" aria-label="Permalink to &quot;14. Phase 6 (Weeks 48-52): Company-specific preparation&quot;">​</a></h3><ul><li>📚 <strong>What to learn</strong>: Target company patterns, their engineering blog, their scale, their known question set. Behavioural preparation.</li><li>🛠️ <strong>What to do</strong>: Study your target company&#39;s architecture publicly. Prepare three of your own project stories in depth.</li><li>🎯 <strong>Milestone / Proof</strong>: You can connect your design choices to that company&#39;s actual problems.</li></ul><hr>',37)])])}const y=t(o,[["render",i]]);export{u as __pageData,y as default};
